import squizStoryRenderer from "@ntgovernment/squiz-factory/plugins/squizStoryRenderer";
import squizInfoMock from "@ntgovernment/squiz-factory/plugins/squizInfo.mock";
import comp from "./main.js";
import { addCustomisationObject, componentCustomisationModifiersType } from '../_utils/stories.helper.js'
const squiz = squizStoryRenderer(comp.main);

export default {
  title: "dxp components/Breadcrumb",
};

function mockInfoForUrl(url) {
  return squizInfoMock({ ctx: { url } });
}

const defaultUrl = "https://example.com/example-section/example-page";
const defaultInfo = mockInfoForUrl(defaultUrl);
const defaultArgs = { customModifiers: '' };
const defaultHtml = await squiz.markup(defaultArgs, defaultInfo);

export const Default = {
  render: (args) => squiz(addCustomisationObject(args, args.customModifiers), defaultInfo),
  args: defaultArgs,
  argTypes: {
    customModifiers: componentCustomisationModifiersType
  },
  
  parameters: {
    controls: {
      exclude: ['componentCustomisation']
    },
    docs: {
      description: { story: `A page two levels deep (${defaultUrl}) -- the full 3-level trail: Home > Example section > Example page.` },
      source: { code: defaultHtml, language: "html", type: "code" },
    },
  },
};

const shallowUrl = "https://example.com/example-page";
const shallowInfo = mockInfoForUrl(shallowUrl);
const shallowHtml = await squiz.markup({}, shallowInfo);

export const Shallow = {
  render: () => squiz({}, shallowInfo),
  parameters: {
    docs: {
      description: { story: `A page directly under Home (${shallowUrl}) -- 2 levels, not padded to 3: Home > Example page.` },
      source: { code: shallowHtml, language: "html", type: "code" },
    },
  },
};

const homepageUrl = "https://example.com/";
const homepageInfo = mockInfoForUrl(homepageUrl);
const homepageHtml = await squiz.markup({}, homepageInfo);

export const Homepage = {
  render: () => squiz({}, homepageInfo),
  parameters: {
    docs: {
      description: { story: "The homepage itself (0 URL segments) -- just \"Home\", rendered as the current, non-linked item." },
      source: { code: homepageHtml, language: "html", type: "code" },
    },
  },
};

const deepUrl = "https://example.com/level-one/level-two/level-three/example-section/example-page";
const deepInfo = mockInfoForUrl(deepUrl);
const deepHtml = await squiz.markup({}, deepInfo);

export const DeepPath = {
  render: () => squiz({}, deepInfo),
  parameters: {
    docs: {
      description: { story: `A page 5 levels deep (${deepUrl}) -- only the 2 segments closest to the current page show; everything nearer Home is dropped silently, no ellipsis: Home > Example section > Example page.` },
      source: { code: deepHtml, language: "html", type: "code" },
    },
  },
};

const hyphenUrl = "https://example.com/example-section/-example-page";
const hyphenInfo = mockInfoForUrl(hyphenUrl);
const hyphenHtml = await squiz.markup({}, hyphenInfo);

export const LeadingHyphenSlug = {
  render: () => squiz({}, hyphenInfo),
  parameters: {
    docs: {
      description: { story: `A slug with a leading hyphen (${hyphenUrl}) -- humanizeSlug() strips it: Home > Example section > Example page.` },
      source: { code: hyphenHtml, language: "html", type: "code" },
    },
  },
};

const cacheBusterUrl = "https://example.com/example-section/example-page/_nocache";
const cacheBusterInfo = mockInfoForUrl(cacheBusterUrl);
const cacheBusterHtml = await squiz.markup({}, cacheBusterInfo);

export const CacheBusterToken = {
  render: () => squiz({}, cacheBusterInfo),
  parameters: {
    docs: {
      description: { story: `A URL with a trailing Squiz cache-buster token (${cacheBusterUrl}) -- filtered out entirely, never rendered as a crumb: Home > Example section > Example page.` },
      source: { code: cacheBusterHtml, language: "html", type: "code" },
    },
  },
};
