export function addCustomisationObject(args = {}, modifiers = '') {
    return {
        ...args,
        componentCustomisation: {
            modifiers: modifiers.split(', ').map(s => s.trim())
        }
    }
}

export const componentCustomisationModifiers = [
    'background: alt',
    'background: inherit',
    'background: transparent',
    'fullwidth background',
    'spacious'
];
export const componentCustomisationModifiersType = {
    control: 'text',
    name: 'componentCustomisation.modifiers (array)',
    description: 'For storybook use comma seperated string of any of these: ' + componentCustomisationModifiers.join(', ')
};