import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";
import { componentAttrs, mergeDefaultModifiers } from "../_utils/component.helper";

/**
 * Never shows more than this many levels (including "Home" and the current
 * page) -- explicit user requirement. Right-truncated: whichever levels are
 * closest to the current page are kept, not the ones closest to Home.
 */
const MAX_LEVELS = 3;

const CHEVRON_RIGHT_SVG =
  '<svg viewBox="0 0 16 16" width="12" height="12" fill="none" aria-hidden="true" focusable="false"><path d="M6 4l4 4-4 4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';

/**
 * Squiz appends cache-control tokens (`_nocache`, `_recache`, optionally
 * `=<value>`) to the end of a page's URL -- not a real path segment, and
 * never part of the page's own tree position. Matched case-insensitively
 * and dropped before any trail/label logic runs, wherever it appears in the
 * path. See breadcrumb.spec.md assumption 4.
 */
const CACHE_BUSTER_PATTERN = /^_?(no|re)cache(=.*)?$/i;

export default {
  async main(input = {}, info = {}) {
    const trail = buildBreadcrumbTrail(info?.ctx?.url);
    const attrs = componentAttrs("breadcrumb", mergeDefaultModifiers(input, ['fullwidth background']));
    return renderBreadcrumb(trail, attrs);
  },
};

/**
 * Builds the breadcrumb trail purely from the current page's own URL --
 * no info.fns call, no editor selection. "Home" is always the site root
 * (the URL's origin); every other level is one path segment, humanized from
 * its slug (see humanizeSlug()) -- after dropping any Squiz cache-buster
 * token (see CACHE_BUSTER_PATTERN), so those never count as a level or get
 * rendered as a bogus crumb. Truncated to the MAX_LEVELS closest to the
 * current page -- if the real path is deeper than that, the levels nearest
 * Home are simply dropped, not abbreviated with an ellipsis. See
 * breadcrumb.spec.md assumption 1.
 */
function buildBreadcrumbTrail(rawUrl) {
  const url = parseUrl(rawUrl);
  const home = { label: "Home", href: url ? `${url.origin}/` : "/" };

  const segments = url
    ? url.pathname
        .split("/")
        .filter(Boolean)
        .filter((segment) => !CACHE_BUSTER_PATTERN.test(segment))
    : [];
  if (segments.length === 0) return [{ ...home, current: true }];

  const visibleSegments = segments.slice(-(MAX_LEVELS - 1));
  const startIndex = segments.length - visibleSegments.length;

  const crumbs = visibleSegments.map((segment, i) => {
    const pathSegments = segments.slice(0, startIndex + i + 1);
    return {
      label: humanizeSlug(segment),
      href: `${url.origin}/${pathSegments.join("/")}`,
      current: i === visibleSegments.length - 1,
    };
  });

  return [home, ...crumbs];
}

function parseUrl(rawUrl) {
  try {
    if (rawUrl instanceof URL) return rawUrl;
    if (typeof rawUrl === "string" && rawUrl) return new URL(rawUrl);
  } catch {
    // fall through
  }
  return null;
}

/**
 * Turns a URL path segment into a display label -- strips stray leading/
 * trailing hyphens (e.g. a "-example-page" slug), splits on hyphens/
 * underscores, joins with spaces, and sentence-cases the result (first
 * letter capitalised, rest lowercase). "example-section" -> "Example
 * section"; "-example-page" -> "Example page". See breadcrumb.spec.md
 * assumption 2.
 */
function humanizeSlug(segment) {
  let text;
  try {
    text = decodeURIComponent(segment);
  } catch {
    text = segment;
  }

  const words = text
    .replace(/^-+|-+$/g, "")
    .split(/[-_]+/)
    .filter(Boolean);
  if (words.length === 0) return segment;

  const joined = words.join(" ").toLowerCase();
  return joined.charAt(0).toUpperCase() + joined.slice(1);
}

function renderBreadcrumb(trail, attrs) {
  const itemsHtml = trail
    .map((crumb, index) => {
      const separatorHtml =
        index > 0
          ? `<span class="breadcrumb__separator" aria-hidden="true">${CHEVRON_RIGHT_SVG}</span>`
          : "";
      const contentHtml = crumb.current
        ? `<span class="breadcrumb__current" aria-current="page">${escHTML(crumb.label)}</span>`
        : `<a class="breadcrumb__link" href="${escURL(crumb.href)}">${escHTML(crumb.label)}</a>`;

      return `<li class="breadcrumb__item">${separatorHtml}${contentHtml}</li>`;
    })
    .join("");

  return /*html*/ `
<nav ${attrs} aria-label="Breadcrumb">
  <ol class="breadcrumb__list">
    ${itemsHtml}
  </ol>
</nav>
`;
}
